package com.warehouse.twin.controller;
import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.warehouse.twin.common.Result; import com.warehouse.twin.dto.AlarmHandleRequest; import com.warehouse.twin.entity.Alarm; import com.warehouse.twin.service.AlarmService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.List;
@RestController @RequestMapping("/api/alarms") public class AlarmController {private final AlarmService s;public AlarmController(AlarmService s){this.s=s;}@GetMapping public Result<List<Alarm>> list(){return Result.ok(s.list(Wrappers.<Alarm>lambdaQuery().orderByDesc(Alarm::getTriggerTime)));}@PutMapping("/{id}/handle")public Result<Alarm> handle(@PathVariable Long id,@Valid @RequestBody AlarmHandleRequest r){Alarm a=s.getById(id);if(a==null)throw new IllegalArgumentException("告警不存在");a.setStatus("HANDLED");a.setHandler(r.handler());a.setRemark(r.remark());a.setHandledAt(LocalDateTime.now());s.updateById(a);return Result.ok(a);}}
